using System;
using System.Collections.Generic;
using UnityEngine;
namespace HotelTogether {
 public enum HotelUpgrade {Rooms,Tools,Security,Staff}
 public enum HotelMisconduct {Grab,Throw,Prop,Shot}
 [Serializable] public sealed class HotelShiftReport {public int day,checkIns,services,cleaning,repairs,kills,deaths,rent,tips,wages,upkeep,fines,bonus,investments,checkInTarget,serviceTarget,incomeTarget;public float rating;public int Revenue=>rent+tips;public int Net=>Revenue+bonus-wages-upkeep-fines-investments;}
 [DefaultExecutionOrder(-35)] public sealed class HotelEconomy:MonoBehaviour {
  const string SaveKey="HotelTogether.Career.v1";public bool persistenceEnabled=true;
  public bool Initialized{get;private set;}public HotelGuestSimulation Hotel{get;private set;}public int Wallet{get;private set;}=250;public float Reputation{get;private set;}=70;public int CompletedDays{get;private set;}public int[] Levels{get;private set;}=new int[4];public HotelShiftReport Shift{get;private set;}=new HotelShiftReport();public HotelShiftReport LastReport{get;private set;}public bool ShopOpen{get;private set;}public bool SummaryOpen{get;private set;}public bool ModalOpen=>ShopOpen||SummaryOpen;public bool AudioEnabled=>Initialized&&Hotel&&Hotel.player&&!Hotel.player.GameplayPaused;
  public int RoomPrice=>80+Levels[0]*25;public float WorkSpeed=>1+Levels[1]*.25f;public float Patience=>1+Levels[0]*.15f;public int CheckInGoal=>Mathf.Min(5,3+CompletedDays/3);public int ServiceGoal=>5+Mathf.Min(4,CompletedDays/3);public int IncomeGoal=>180+Mathf.Min(16,CompletedDays)*15;
  int baseGuests;float baseArrival,baseGrace;long serial;float staffTick;readonly Dictionary<long,HotelCash> receipts=new();readonly Dictionary<(HotelGuestBot,HotelMisconduct),float> conductCooldown=new();readonly HashSet<HotelHuman> dead=new();readonly List<string> reviews=new();readonly List<HotelStaffBot> staff=new();readonly Dictionary<HotelDefenseOpening,float> defenseBase=new();readonly List<GameObject> decor=new();Material luxury;
  public IReadOnlyList<string> Reviews=>reviews;public IReadOnlyList<HotelStaffBot> Staff=>staff;readonly Dictionary<UnityEngine.Object,HotelStaffBot> staffClaims=new();public bool ClaimStaffJob(UnityEngine.Object job,HotelStaffBot worker){if(!job||!worker)return false;if(staffClaims.TryGetValue(job,out var other)&&other&&other!=worker)return false;staffClaims[job]=worker;return true;}public void SaveStaffSettings(){SaveCareer();}
  public void ReleaseStaffJob(UnityEngine.Object job,HotelStaffBot worker){if(!ReferenceEquals(job,null)&&staffClaims.TryGetValue(job,out var owner)&&owner==worker)staffClaims.Remove(job);}
  [Serializable] class SaveData {public int version=1,wallet=250,days;public float reputation=70;public int[] levels=new int[4];public int[] duties;public bool[] onDuty;}
  void Start(){var h=GetComponent<HotelGuestSimulation>();if(h&&h.rooms!=null&&h.rooms.Length>0)Initialize(h);}
  public void Initialize(HotelGuestSimulation h,bool restore=true){if(Initialized||!h)return;Hotel=h;baseGuests=h.maxGuests;baseArrival=h.arrivalInterval;h.daySeconds=Mathf.Max(h.daySeconds,420);var director=FindAnyObjectByType<HotelZombieDirector>();baseGrace=director?director.nightGrace:12;Initialized=true;
   if(restore&&persistenceEnabled&&PlayerPrefs.HasKey(SaveKey)){try{var save=JsonUtility.FromJson<SaveData>(PlayerPrefs.GetString(SaveKey));if(save!=null&&save.version==1&&save.levels!=null&&save.levels.Length==4&&float.IsFinite(save.reputation)){Wallet=Mathf.Clamp(save.wallet,-1000000,1000000);Reputation=Mathf.Clamp(save.reputation,0,100);CompletedDays=Mathf.Clamp(save.days,0,10000);for(int i=0;i<4;i++)Levels[i]=Mathf.Clamp(save.levels[i],0,i==3?6:3);h.SetCareerDay(CompletedDays+1);}}catch(Exception e){Debug.LogWarning("Career save unreadable; starting a fresh career: "+e.Message);}}
   Shift=new HotelShiftReport{day=h.DayNumber};ApplyUpgrades();if(restore&&persistenceEnabled)LoadStaffRoster();}
  void LoadStaffRoster(){if(!PlayerPrefs.HasKey(SaveKey))return;try{var roster=JsonUtility.FromJson<SaveData>(PlayerPrefs.GetString(SaveKey));if(roster==null)return;for(int i=0;i<staff.Count;i++){if(roster.duties!=null&&i<roster.duties.Length&&Enum.IsDefined(typeof(StaffDuty),roster.duties[i]))staff[i].Duty=(StaffDuty)roster.duties[i];if(roster.onDuty!=null&&i<roster.onDuty.Length)staff[i].OnDuty=roster.onDuty[i];}}catch(Exception){/* Invalid career data already reported by Initialize. */}}
  public long RegisterCash(HotelCash cash){if(!Initialized||!cash)return 0;long id=++serial;receipts[id]=cash;return id;}
  public void CancelCash(long id){receipts.Remove(id);}
  public bool ReceiveCash(HotelCash cash,long id,int rent,int tip){if(!Initialized||!cash||!receipts.TryGetValue(id,out var expected)||expected!=cash||!cash.Paid||rent!=cash.Rent||tip!=cash.Tip||rent<0||tip<0||rent+tip<=0)return false;receipts.Remove(id);Wallet+=rent+tip;Hotel.AddCollectedTip(tip);Shift.rent+=rent;Shift.tips+=tip;Hotel.player?.Notify("Received $"+(rent+tip)+(rent>0?" room payment":" tip")+". Wallet $"+Wallet);Hotel.player?.PlayFeedback(HotelFeedback.Cash);return true;}
  public void CheckIn(HotelGuestBot g){if(!Initialized||!g||!g.CheckedIn)return;Shift.checkIns++;}
  public int QuoteTip(HotelGuestBot g,int baseTip)=>!g||g.Payment&&g.Payment.TipsBlocked?0:Mathf.RoundToInt(baseTip*Mathf.Lerp(.15f,1,g.Satisfaction)*(1+Levels[0]*.1f)*Mathf.Lerp(.6f,1.15f,Mathf.Clamp(Reputation+.35f,0,100)/100));
  public void Service(HotelGuestBot g,int baseTip,bool offerTip=true){if(!Initialized||!g)return;int tip=QuoteTip(g,baseTip);Shift.services++;Reputation=Mathf.Clamp(Reputation+.35f,0,100);if(offerTip&&tip>0)g.Payment?.Offer(0,tip);}
  public void Housekeeping(int amount,bool repair=false){if(!Initialized)return;if(repair)Shift.repairs++;else Shift.cleaning++;Wallet+=Mathf.Max(0,amount);Shift.tips+=Mathf.Max(0,amount);Reputation=Mathf.Clamp(Reputation+.3f,0,100);}
  public void Review(HotelGuestBot g,bool abandoned=false){if(!Initialized||!g)return;float rating=Mathf.Clamp01(g.Satisfaction);Reputation=Mathf.Clamp(Reputation+(abandoned?-3:Mathf.Lerp(-3,2.5f,rating)),0,100);string text=g.guestName+": "+(abandoned?"Left after waiting too long":rating>.8f?"Great service. I will be back!":rating>.45f?"An okay stay, but service could improve.":"Poor service. I cannot recommend this hotel.");reviews.Insert(0,text);if(reviews.Count>5)reviews.RemoveAt(5);g.PrankPhysics?.Say(text);}
  public void Misconduct(HotelGuestBot victim,HotelMisconduct kind){if(!Initialized||!victim)return;var key=(victim,kind);if(conductCooldown.TryGetValue(key,out float until)&&Time.time<until)return;conductCooldown[key]=Time.time+(kind==HotelMisconduct.Shot?.25f:6);float penalty=kind==HotelMisconduct.Shot?5:kind==HotelMisconduct.Throw?4:2;int fine=kind==HotelMisconduct.Shot?20:kind==HotelMisconduct.Throw?8:3;Reputation=Mathf.Max(0,Reputation-penalty);Wallet-=fine;Shift.fines+=fine;victim.Payment?.Withdraw();if(kind==HotelMisconduct.Shot||kind==HotelMisconduct.Prop)victim.GetComponent<HotelGuestSurvival>()?.OnPlayerThreat();foreach(var witness in Hotel.Guests)if(witness&&witness!=victim&&Vector3.Distance(witness.transform.position,victim.transform.position)<7){witness.Payment?.Withdraw();if(kind==HotelMisconduct.Shot||kind==HotelMisconduct.Prop)witness.GetComponent<HotelGuestSurvival>()?.OnPlayerThreat();}Hotel.player?.Notify("Guest complaint: reputation -"+penalty+", compensation $"+fine+".");}
  public void Death(HotelHuman human,bool murdered=false){if(!Initialized||!human||!dead.Add(human))return;Shift.deaths++;Reputation=Mathf.Max(0,Reputation-(murdered?20:7));if(murdered){Wallet-=180;Shift.fines+=180;}human.Guest?.Payment?.Withdraw();}
  public void Kill(){if(Initialized)Shift.kills++;}
  public int Price(HotelUpgrade upgrade){int index=(int)upgrade;if(index<0||index>=4)return int.MaxValue;int level=Levels[index];int basis=upgrade==HotelUpgrade.Rooms?180:upgrade==HotelUpgrade.Tools?120:upgrade==HotelUpgrade.Security?140:180;return basis+level*(upgrade==HotelUpgrade.Staff?100:100);}
  public bool Purchase(HotelUpgrade upgrade){int index=(int)upgrade;if(!Initialized||index<0||index>=4||Levels[index]>=(index==3?6:3)||Wallet<Price(upgrade))return false;int price=Price(upgrade);Wallet-=price;Levels[index]++;ApplyUpgrades();if(upgrade==HotelUpgrade.Staff&&staff.Count<2+Levels[index]){Wallet+=price;Levels[index]--;ApplyUpgrades();Hotel.player?.Notify("No walkable staff spawn point. No money charged.");return false;}Shift.investments+=price;SaveCareer();Hotel.player?.PlayFeedback(HotelFeedback.Cash);return true;}
  public bool FinishDay(int day){if(!Initialized||LastReport!=null&&LastReport.day>=day)return false;Shift.checkInTarget=CheckInGoal;Shift.serviceTarget=ServiceGoal;Shift.incomeTarget=IncomeGoal;Shift.day=day;Shift.rating=Reputation;Shift.upkeep=95;Shift.wages=Levels[3]*45;Shift.bonus=(Shift.checkIns>=CheckInGoal?25:0)+(Shift.services>=ServiceGoal?25:0)+(Shift.Revenue>=IncomeGoal?25:0)+(Reputation>=65?15:0)+(Shift.deaths==0&&Shift.checkIns>0?30:0);Wallet+=Shift.bonus-Shift.upkeep-Shift.wages;CompletedDays++;LastReport=Shift;SummaryOpen=true;ShopOpen=false;Hotel.player?.PauseGameplay();SaveCareer();return true;}
  public void ContinueDay(){if(!SummaryOpen)return;SummaryOpen=false;Shift=new HotelShiftReport{day=Hotel.DayNumber};dead.Clear();conductCooldown.Clear();ApplyUpgrades();foreach(var guest in Hotel.Guests)if(guest)guest.OnPeriodChanged();Hotel.player?.ResumeGameplay();}
  public void OpenShop(){if(!Initialized||SummaryOpen||Hotel.player&&Hotel.player.combat&&Hotel.player.combat.IsDown)return;ShopOpen=true;Hotel.player?.PauseGameplay();}
  public void CloseShop(){ShopOpen=false;Hotel.player?.ResumeGameplay();}
  void SaveCareer(){if(!persistenceEnabled)return;var save=new SaveData{wallet=Wallet,reputation=Reputation,days=CompletedDays,levels=(int[])Levels.Clone(),duties=staff.ConvertAll(w=>(int)w.Duty).ToArray(),onDuty=staff.ConvertAll(w=>w.OnDuty).ToArray()};PlayerPrefs.SetString(SaveKey,JsonUtility.ToJson(save));PlayerPrefs.Save();}
  public void ResetCareer(){if(!Initialized)return;foreach(var cash in new List<HotelCash>(receipts.Values))if(cash)cash.Void();receipts.Clear();Wallet=250;Reputation=70;CompletedDays=0;Levels=new int[4];LastReport=null;Shift=new HotelShiftReport{day=1};SummaryOpen=ShopOpen=false;dead.Clear();conductCooldown.Clear();reviews.Clear();foreach(var worker in staff){worker.SetDuty(StaffDuty.All);worker.SetOnDuty(true);}if(persistenceEnabled)PlayerPrefs.DeleteKey(SaveKey);Hotel.SetCareerDay(1);ApplyUpgrades();}
  public void ApplyUpgrades(){if(!Initialized)return;Hotel.maxGuests=Mathf.Min(Hotel.rooms.Length,baseGuests+Levels[0]);Hotel.arrivalInterval=baseArrival*Mathf.Lerp(1.7f,.85f,Reputation/100);var director=FindAnyObjectByType<HotelZombieDirector>();if(director&&director.hotel==Hotel)director.nightGrace=baseGrace+Levels[2]*5;foreach(var opening in FindObjectsByType<HotelDefenseOpening>(FindObjectsSortMode.None)){if(!defenseBase.ContainsKey(opening))defenseBase[opening]=opening.structureMax;opening.ApplyUpgrade(defenseBase[opening]*(1+Levels[2]*.25f));}
   foreach(var go in decor)if(go)Destroy(go);decor.Clear();if(Levels[0]>0){if(!luxury){luxury=new Material(Shader.Find("Universal Render Pipeline/Lit")??Shader.Find("Standard"));luxury.color=new Color(.32f,.57f,.51f);}foreach(var room in Hotel.rooms)if(room.bed){var pillow=GameObject.CreatePrimitive(PrimitiveType.Cube);pillow.name="Upgraded room cushion";pillow.transform.SetParent(room.bed,false);pillow.transform.localPosition=new Vector3(0,.40f,.45f);pillow.transform.localScale=new Vector3(.5f,.08f,.30f);pillow.GetComponent<Renderer>().sharedMaterial=luxury;Destroy(pillow.GetComponent<Collider>());decor.Add(pillow);}}
   while(staff.Count>2+Levels[3]){var last=staff[staff.Count-1];staff.RemoveAt(staff.Count-1);if(last)Destroy(last.gameObject);}while(staff.Count<2+Levels[3]){var helper=HotelStaffBot.Create(this,staff.Count);if(!helper)break;staff.Add(helper);}}
  void Update(){if(!Initialized||!Hotel.Running)return;staffTick+=Time.deltaTime;if(staffTick>8){staffTick=0;Hotel.arrivalInterval=baseArrival*Mathf.Lerp(1.7f,.85f,Reputation/100);}}
  void OnDestroy(){foreach(var helper in staff)if(helper)Destroy(helper.gameObject);if(luxury)Destroy(luxury);}
 }
}
